const input = $input.first().json;
const event = input.body;
const errors = [];
const required = ['event_id','event_type','timestamp','service_id','severity','source','message'];
if (event === null || typeof event !== 'object' || Array.isArray(event)) {
  errors.push('request body must be a JSON object');
} else {
  for (const f of required) {
    if (typeof event[f] !== 'string' || event[f].trim() === '') errors.push(f + ' is required');
  }
  if (event.metadata !== undefined && (event.metadata === null || typeof event.metadata !== 'object' || Array.isArray(event.metadata))) {
    errors.push('metadata must be an object');
  }
}
if (errors.length) {
  return [{ json: { valid: false, httpStatus: 400, body: { outcome: 'REJECTED', reason: 'malformed_event', errors } } }];
}
return [{ json: { valid: true, event } }];

// Orchestration only: classify the PulseOps response. No policy decisions are made here.
const res = $input.first().json;
const event = $('Validate Event').first().json.event;
const ctx = { event_id: event.event_id, n8n_execution_id: $execution.id };
const status = res.statusCode;
const body = (res.body && typeof res.body === 'object') ? res.body : null;
const err = (httpStatus, reason, detail) => [{ json: { route: 'error', httpStatus, body: { outcome: 'ERROR', reason, ...ctx, detail: (typeof detail === 'string' ? detail.slice(0, 300) : undefined) } } }];

if (status === undefined || status === null) return err(502, 'pulseops_unavailable');
if (status === 401) return err(502, 'pulseops_unauthorized'); // n8n credential missing/invalid: fail closed
if (status === 403) return err(502, 'pulseops_forbidden');
if (status === 404) return err(404, 'not_found', body && body.detail);
if (status === 409) return err(409, 'conflict', body && body.detail);
if (status === 400 || status === 422) return err(400, 'rejected_by_pulseops');
if (status >= 500) return err(502, 'pulseops_error');
if (status < 200 || status >= 300 || !body) return err(502, 'unexpected_response');

// A degraded or failed investigation is never success. PulseOps already closed the workflow (rejected, not a
// policy decision); n8n only reports the investigation outcome and the failure reason.
if (body.investigation_status === 'degraded') return err(502, 'investigation_degraded', body.failure_reason);
if (body.investigation_status === 'failed') return err(502, 'investigation_failed', body.failure_reason);

const known = ['allow', 'notify', 'hitl_required', 'deny'];
const decision = String(body.policy_decision || '').toLowerCase();
if (!known.includes(decision) || !body.workflow_id || !body.incident_id) {
  return err(502, 'unexpected_response');
}
if (body.investigation_status !== 'completed') return err(502, 'unexpected_response');
const route = (decision === 'allow' || decision === 'notify') ? 'notify' : (decision === 'hitl_required' ? 'hitl' : 'deny');
return [{ json: { route, pulseops: body, ctx } }];

const p = $json.pulseops; const ctx = $json.ctx;
const ids = { event_id: ctx.event_id, incident_id: p.incident_id, workflow_id: p.workflow_id, correlation_id: p.correlation_id, n8n_execution_id: ctx.n8n_execution_id };
const investigation = { status: p.investigation_status, summary: p.investigation && p.investigation.summary, confidence: p.investigation && p.investigation.confidence };

// SIMULATED notification only. Nothing is sent to any external system.
return [{ json: { httpStatus: 200, body: { outcome: 'NOTIFIED_SIMULATED', ...ids,
  policy_decision: p.policy_decision, risk_level: p.risk_level, workflow_status: p.status,
  idempotent_replay: p.idempotent_replay, investigation,
  simulated_notification: { channel: 'simulated', summary: 'Incident ' + p.incident_id + ' workflow ' + p.workflow_id + ' policy=' + p.policy_decision } } } }];

const p = $json.pulseops; const ctx = $json.ctx;
const ids = { event_id: ctx.event_id, incident_id: p.incident_id, workflow_id: p.workflow_id, correlation_id: p.correlation_id, n8n_execution_id: ctx.n8n_execution_id };
const investigation = { status: p.investigation_status, summary: p.investigation && p.investigation.summary, confidence: p.investigation && p.investigation.confidence };

// No action is executed. A human must decide through the existing PulseOps approval API.
return [{ json: { httpStatus: 202, body: { outcome: 'HITL_PENDING', ...ids,
  policy_decision: p.policy_decision, risk_level: p.risk_level, workflow_status: p.status,
  idempotent_replay: p.idempotent_replay, investigation,
  approval: { method: 'POST', path: '/workflow/' + p.workflow_id + '/decision',
    required_fields: ['decision (approve|reject)', 'reviewer (human)', 'incident_id', 'action', 'timestamp'],
    incident_id: p.incident_id, action: p.action } } } }];

const p = $json.pulseops; const ctx = $json.ctx;
const ids = { event_id: ctx.event_id, incident_id: p.incident_id, workflow_id: p.workflow_id, correlation_id: p.correlation_id, n8n_execution_id: ctx.n8n_execution_id };
const investigation = { status: p.investigation_status, summary: p.investigation && p.investigation.summary, confidence: p.investigation && p.investigation.confidence };

// DENY is terminal. n8n cannot override it.
return [{ json: { httpStatus: 403, body: { outcome: 'DENIED', ...ids,
  policy_decision: p.policy_decision, workflow_status: p.status, reason: p.policy_reason,
  idempotent_replay: p.idempotent_replay, investigation } } }];
